import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router, RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router';
import { AuthService } from './core/services/auth.service';
import { I18nService } from './core/i18n/i18n.service';
import { TranslatePipe } from './core/i18n/translate.pipe';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, RouterOutlet, RouterLink, RouterLinkActive, TranslatePipe],
  template: `
    <div class="shell" [class.rtl]="i18n.isRtl" *ngIf="auth.currentUser() as user; else bare">
      <aside class="sidebar">
        <div class="brand">⚡ {{ 'brand.name' | translate }}</div>
        <nav>
          <a routerLink="/tasks" routerLinkActive="active">{{ 'nav.tasks' | translate }}</a>
          <a routerLink="/definitions" routerLinkActive="active">{{ 'nav.workflows' | translate }}</a>
          <a routerLink="/designer" routerLinkActive="active">{{ 'nav.newFlow' | translate }}</a>
          <a routerLink="/instances" routerLinkActive="active">{{ 'nav.instances' | translate }}</a>
          <a routerLink="/origins" routerLinkActive="active">{{ 'nav.origins' | translate }}</a>
        </nav>
        <div class="user-box">
          <button class="lang-toggle" (click)="i18n.toggle()">🌐 {{ 'common.language' | translate }}</button>
          <div class="user-name">{{ user.displayName }}</div>
          <div class="user-role">{{ user.role }}</div>
          <button (click)="logout()">{{ 'nav.signOut' | translate }}</button>
        </div>
      </aside>
      <main class="content">
        <router-outlet />
      </main>
    </div>
    <ng-template #bare><router-outlet /></ng-template>
  `,
  styles: [`
    .shell { display: flex; height: 100vh; }
    .shell.rtl { direction: rtl; }
    .sidebar {
      width: 220px;
      background: var(--panel);
      border-right: 1px solid var(--border);
      display: flex;
      flex-direction: column;
      padding: 16px 0;
      flex-shrink: 0;
    }
    .shell.rtl .sidebar { border-right: none; border-left: 1px solid var(--border); }
    .brand { font-weight: 700; font-size: 16px; padding: 0 20px 20px; color: var(--text); }
    nav { display: flex; flex-direction: column; gap: 2px; }
    nav a {
      padding: 10px 20px;
      color: var(--text-dim);
      text-decoration: none;
      font-size: 14px;
      border-left: 3px solid transparent;
    }
    .shell.rtl nav a { border-left: none; border-right: 3px solid transparent; }
    nav a:hover { background: var(--panel-2); color: var(--text); }
    nav a.active { color: var(--text); border-left-color: var(--accent); background: var(--panel-2); }
    .shell.rtl nav a.active { border-left-color: transparent; border-right-color: var(--accent); }
    .user-box { margin-top: auto; padding: 14px 20px; border-top: 1px solid var(--border); display: flex; flex-direction: column; gap: 6px; }
    .lang-toggle { width: 100%; font-size: 11px; padding: 5px; margin-bottom: 4px; }
    .user-name { font-size: 13px; font-weight: 600; }
    .user-role { font-size: 11px; color: var(--text-dim); text-transform: capitalize; }
    .user-box button { width: 100%; font-size: 11px; padding: 5px; }
    .content { flex: 1; overflow: auto; }
  `]
})
export class AppComponent {
  constructor(public auth: AuthService, private router: Router, public i18n: I18nService) {}

  logout() {
    this.auth.logout();
    this.router.navigate(['/login']);
  }
}
